/**
 * @summary Download a specific week's Excel arrangement
 */
export const getDownloadArrangementUrl = (weekIndex: number) => {
  return `/api/arrangements/download/${weekIndex}`;
};

export const downloadArrangement = async (
  weekIndex: number,
  options?: RequestInit,
): Promise<Blob> => {
  return customFetch<Blob>(getDownloadArrangementUrl(weekIndex), {
    ...options,
    method: "GET",
  });
};

export const getDownloadArrangementQueryKey = (weekIndex: number) => {
  return [`/api/arrangements/download/${weekIndex}`] as const;
};

export const getDownloadArrangementQueryOptions = <
  TData = Awaited<ReturnType<typeof downloadArrangement>>,
  TError = ErrorType<void>,
>(
  weekIndex: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof downloadArrangement>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getDownloadArrangementQueryKey(weekIndex);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof downloadArrangement>>
  > = ({ signal }) =>
    downloadArrangement(weekIndex, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!weekIndex,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof downloadArrangement>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type DownloadArrangementQueryResult = NonNullable<
  Awaited<ReturnType<typeof downloadArrangement>>
>;
export type DownloadArrangementQueryError = ErrorType<void>;

/**
 * @summary Download a specific week's Excel arrangement
 */

export function useDownloadArrangement<
  TData = Awaited<ReturnType<typeof downloadArrangement>>,
  TError = ErrorType<void>,
>(
  weekIndex: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof downloadArrangement>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getDownloadArrangementQueryOptions(weekIndex, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}

